/* Manual item pickup; ordinary shard/ore/pearl income remains automatic. */
const GroundLoot=(()=>{
    const M=MageItemLoot,positions=[{x:47,y:56},{x:66,y:63},{x:83,y:64}];
    let page=0,lastPickup=null,clearTimer=null;
    const pending=()=>state.groundLoot.pending;
    const titleOf=i=>i.kind==='spell'?i.key:i.kind==='spirit'?MageVentureSpirits.find(i.key)?.name||i.key:familiar(Number(i.key)).name;
    const artOf=i=>i.kind==='spell'?spell(i.key)?.art||'book':i.kind==='spirit'?MageVentureSpirits.find(i.key)?.art||'spirit':familiar(Number(i.key)).art;
    function syncDiscoveries(){for(const name of state.realmFinds.pending||[]){const d=MageIdleSpells.definitions.find(d=>d.name===name);const report=state.realmFinds.receipts.find(r=>r.found.includes(name));if(d)M.queue(state.groundLoot,{id:'realm-find-'+d.id,kind:'spell',key:name,realm:d.realm,rarity:2,source:report?.source||'idle'});}}
    function dropMarkup(item){const p=positions[item.slot];return `<button class="ground-drop rarity-${item.rarity}" data-ground-pick="${item.id}" style="--loot-color:${MageRarity.colors[item.rarity]};left:${p.x}%;top:${p.y}%" aria-label="Pick up ${MageRarity.tiers[item.rarity]} ${esc(titleOf(item))}"><i class="loot-beam"></i><i class="loot-ring"></i><i class="loot-sparks"></i>${sprite(artOf(item))}<small>${MageRarity.tiers[item.rarity]}</small></button>`;}
    function view(){const here=pending().filter(i=>i.realm===state.realm&&i.slot!==null),all=pending().length,burst=lastPickup?.session===state&&lastPickup.realm===state.realm?lastPickup:null;return `<div class="ground-loot-layer" aria-label="Item drops waiting for pickup">${here.map(dropMarkup).join('')}${all?`<button class="loot-stash" data-ground-items aria-label="View all ${all} waiting item drops">${ui('book')}<b>${all}</b><small>Items</small></button>`:''}${burst?`<div class="loot-pickup-burst" style="left:${burst.x}%;top:${burst.y}%;--loot-color:${burst.color}" aria-hidden="true">${sprite(burst.art)}${Array.from({length:8},(_,i)=>`<i style="--spark-angle:${i*45}deg"></i>`).join('')}</div>`:''}</div>`;}
    function refresh(){const old=phone.querySelector('.ground-loot-layer');if(old)old.outerHTML=view();}
    function modal(){const all=pending(),pages=Math.max(1,Math.ceil(all.length/12));page=Math.min(page,pages-1);return `<div class="collection-meta">${all.length} waiting · Tap an item to collect</div><div class="collection-grid ground-items-grid">${all.slice(page*12,(page+1)*12).map(i=>`<button class="collection-card pending-item" data-ground-pick="${i.id}" style="--loot-color:${MageRarity.colors[i.rarity]}" aria-label="Pick up ${MageRarity.tiers[i.rarity]} ${esc(titleOf(i))}">${sprite(artOf(i))}<strong>${esc(titleOf(i))}</strong><small>${MageRarity.tiers[i.rarity]} · ${realms[i.realm]}</small><span>Pick up</span></button>`).join('')}</div>${!all.length?'<p class="no-results">All items collected</p>':''}${pages>1?`<div class="pagination"><button data-ground-page="-1" aria-label="Previous waiting items" ${page===0?'disabled':''}>←</button><span>${page+1} / ${pages}</span><button data-ground-page="1" aria-label="Next waiting items" ${page===pages-1?'disabled':''}>→</button></div>`:''}<p class="ground-retention">${ui('lock')} Kept until you pick them up</p>`;}
    function collect(id){const item=pending().find(i=>i.id===id);if(!item)return;const out=M.collect(state,id);if(!out.ok||out.duplicate)return;const p=positions[item.slot]||{x:60,y:63};lastPickup={session:state,realm:item.realm,x:p.x,y:p.y,art:artOf(item),color:MageRarity.colors[item.rarity]};clearTimeout(clearTimer);const session=state;clearTimer=setTimeout(()=>{if(state===session){lastPickup=null;phone.querySelector('.loot-pickup-burst')?.remove();}},1000);if(state.modal?.type==='groundItems'&&!pending().length)state.modal=null;notify(out.receipt.converted?titleOf(item)+' · Duplicate → +10 Ore':titleOf(item)+' · Collected');if(item.kind==='spirit')openModal({type:'spiritDrop',id:'loot-'+id});else if(state.modal?.type==='groundItems')phone.querySelector('.pending-item')?.focus();}
    function handle(el){if(el.dataset.groundPick){collect(el.dataset.groundPick);return true;}if(el.hasAttribute('data-ground-items')){page=0;openModal({type:'groundItems'});return true;}if(el.dataset.groundPage){page+=Number(el.dataset.groundPage);render(true);return true;}return false;}
    function seed(count=3){const samples=[{kind:'spell',key:'Firebolt',rarity:4},{kind:'spirit',key:'echo',rarity:3},{kind:'familiar',key:'12',rarity:2}];for(let n=0;n<count;n++)M.queue(state.groundLoot,{...samples[n%3],id:'review-item-'+n,realm:0,source:'review'});}
    function dropFromKill(){if(state.kills===0||state.kills%5)return;const n=state.kills/5,spirit=n%2===1;M.queue(state.groundLoot,{id:state.realmFindWindow+'-item-'+state.kills,kind:spirit?'spirit':'familiar',key:spirit?['delver','weaver','echo'][n%3]:String(10+n),rarity:spirit?3:2,realm:state.realm,source:'idle'});refresh();}
    return {syncDiscoveries,view,refresh,modal,collect,handle,seed,dropFromKill,pending,titleOf};
})();
